(() => {
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),mini=document.getElementById('minimap'),mctx=mini.getContext('2d');
const W=3200,H=2400,ROAD=108,CELL=400,TAU=Math.PI*2;
const $=id=>document.getElementById(id);
let vw=innerWidth,vh=innerHeight,dpr=1,camera={x:0,y:0},running=false,paused=false,dialogOpen=false,toastTimer;
function resize(){vw=innerWidth;vh=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=vw*dpr;canvas.height=vh*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
const seedRandom=(seed)=>()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
const rand=seedRandom(4097), buildings=[],parks=[],trees=[],shops=[];
const districtNames=['CENTRO VELHO','MARINA AZUL','BAIRRO ALTO','PORTO LESTE','JARDINS DO SUL','MERCADO CENTRAL'];
const districtOf=(x,y)=>{if(x>2350&&y<950)return 'MARINA AZUL';if(y>1700)return x<1650?'PORTO LESTE':'JARDINS DO SUL';if(x<850)return 'BAIRRO ALTO';if(x>2350)return 'MERCADO CENTRAL';return 'CENTRO VELHO'};
for(let gy=0;gy<6;gy++)for(let gx=0;gx<8;gx++){
 const bx=gx*CELL+ROAD/2+15,by=gy*CELL+ROAD/2+15,bw=CELL-ROAD-30,bh=CELL-ROAD-30;
 if(rand()<.15){parks.push({x:bx,y:by,w:bw,h:bh});for(let i=0;i<8;i++)trees.push({x:bx+20+rand()*(bw-40),y:by+20+rand()*(bh-40),r:8+rand()*8});continue}
 const n=2+Math.floor(rand()*3);
 for(let i=0;i<n;i++){
  const cols=n===2?2:3,rows=Math.ceil(n/cols),cw=bw/cols,ch=bh/rows;
  const x=bx+(i%cols)*cw+7+rand()*10,y=by+Math.floor(i/cols)*ch+7+rand()*9;
  const w=cw-18-rand()*12,h=ch-18-rand()*12;
  buildings.push({x,y,w,h,tall:rand(),hue:Math.floor(rand()*360),roof:rand()});
 }
 if(rand()<.48)shops.push({x:bx+bw/2,y:by+bh/2,kind:rand()<.5?'MERCADO':'OFICINA'});
}
const player={x:1050,y:800,a:0,speed:0,r:12,car:false,color:'#dc8d64',outfit:'#e7d45b',name:'Maya Costa',role:'CORREDORA'};
const car={x:1125,y:820,a:0,speed:0,color:'#d4e356',name:'SENTINEL',fuel:100};
const cargo=[];let money=1250,rep=0,characterIndex=0,objectiveIndex=0,missionIndex=0,gameTime=21*60+40;
const characters=[{name:'Maya Costa',role:'CORREDORA',color:'#dc8d64',outfit:'#e7d45b'},{name:'Ravi Nunes',role:'MECÂNICO',color:'#955f48',outfit:'#57bca7'},{name:'Luna Reis',role:'DJ · INFORMANTE',color:'#efb99b',outfit:'#ac7ddd'}];
const missions=[
 {title:'Uma noite longa',steps:[{x:1470,y:800,label:'Encontre Léo no Mirante',desc:'Léo está esperando perto do mirante. Descubra por que ele ligou tão tarde.',kind:'talk'},{x:280,y:1960,label:'Pegue a encomenda no Mercado',desc:'Pegue uma carga misteriosa no Mercado Central. Sem perguntas, por enquanto.',kind:'pickup'},{x:2660,y:760,label:'Entregue para Nina na Marina',desc:'Nina está perto dos barcos. Faça a entrega e volte para a cidade.',kind:'deliver'}],reward:650,rep:1},
 {title:'Sinal perdido',steps:[{x:2350,y:1450,label:'Procure o sinal no Porto',desc:'Um rádio de Léo parou de responder. Procure a origem do sinal no Porto Leste.',kind:'search'},{x:860,y:330,label:'Leve o rádio até Ravi',desc:'Ravi consegue consertar qualquer coisa. Leve o rádio até a oficina dele.',kind:'deliver'}],reward:900,rep:2},
 {title:'Corrida contra o tempo',steps:[{x:650,y:1250,label:'Encontre Jo na avenida',desc:'Jo quer testar seu carro em um circuito improvisado. Chegue até ela.',kind:'talk'},{x:2550,y:1950,label:'Cruze a linha de chegada',desc:'Entre em um veículo e alcance a linha de chegada no sul da cidade.',kind:'race'}],reward:1200,rep:3},
 {title:'Neon até o amanhecer',steps:[{x:1600,y:400,label:'Vá ao terraço da Torre Neon',desc:'A cidade parece diferente lá de cima. É hora de decidir o que vem depois.',kind:'final'}],reward:2000,rep:5}
];
function activeStep(){return missions[Math.min(missionIndex,missions.length-1)].steps[objectiveIndex]}
function showToast(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2300)}
function save(){try{localStorage.setItem('neonbay-save',JSON.stringify({money,rep,missionIndex,objectiveIndex,cargo,characterIndex,player:{x:player.x,y:player.y},car:{x:car.x,y:car.y}}))}catch(e){}}
function load(){try{const s=JSON.parse(localStorage.getItem('neonbay-save')||'null');if(s){money=s.money??money;rep=s.rep??0;missionIndex=s.missionIndex??0;objectiveIndex=s.objectiveIndex??0;cargo.splice(0,4,...(s.cargo||[]));characterIndex=s.characterIndex??0;if(s.player)Object.assign(player,s.player);if(s.car)Object.assign(car,s.car);applyCharacter()}}catch(e){}}
load();
function applyCharacter(){const c=characters[characterIndex];player.name=c.name;player.role=c.role;player.color=c.color;player.outfit=c.outfit;$('charName').textContent=c.name;$('charRole').textContent=`${c.role} · NÍVEL ${rep+1}`;$('avatar').textContent=c.name.split(' ').map(x=>x[0]).join('');$('avatar').style.background=`linear-gradient(135deg,${c.color},${c.outfit})`}
function formatMoney(n){return n.toLocaleString('pt-BR')}
function updateHUD(){const m=missions[Math.min(missionIndex,missions.length-1)],s=activeStep();$('cash').textContent=formatMoney(money);$('rep').textContent=rep;$('missionTitle').textContent=missionIndex>=missions.length?'Cidade aberta':m.title;$('missionText').textContent=missionIndex>=missions.length?'A história terminou. A cidade continua sendo sua. Explore, personalize e faça negócios.':s.desc;$('missionStep').textContent=missionIndex>=missions.length?'MUNDO ABERTO':`OBJETIVO ${objectiveIndex+1} / ${m.steps.length}`;$('district').textContent=districtOf(player.x,player.y);const dist=Math.round(Math.hypot(s.x-player.x,s.y-player.y));$('distance').textContent=missionIndex>=missions.length?'LIVRE':`${dist} M`;const slots=$('cargoSlots');slots.innerHTML='';for(let i=0;i<4;i++){const d=document.createElement('div');d.className='cargo-slot'+(cargo[i]?' filled':'');d.textContent=cargo[i]?cargo[i].icon:'+';if(cargo[i])d.title=cargo[i].name;slots.appendChild(d)}$('cargoCount').textContent=`${cargo.length} / 4`;if(player.car){$('vehicleHud').classList.remove('hidden');$('speed').textContent=Math.round(Math.abs(car.speed)*.38);$('fuelBar').style.width=car.fuel+'%'}else $('vehicleHud').classList.add('hidden')}
function worldToScreen(x,y){return{x:x-camera.x+vw/2,y:y-camera.y+vh/2}}
const keys={};
addEventListener('keydown',e=>{const k=e.key.toLowerCase();keys[k]=true;if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(k==='e'&&!dialogOpen&&running)interact();if(k==='escape'){if(dialogOpen)closeDialog();else togglePause()}if(k==='m'&&!dialogOpen)openTrade()});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
function near(x,y,r=70){return Math.hypot((player.car?car.x:player.x)-x,(player.car?car.y:player.y)-y)<r}
function currentPos(){return player.car?car:player}
function markerPos(){return activeStep()}
function interact(){const p=currentPos();if(player.car){if(near(car.x,car.y,1)){player.car=false;player.x=car.x+20;player.y=car.y+10;car.speed=0;showToast('Você saiu do veículo.');return}}
 if(!player.car&&Math.hypot(p.x-car.x,p.y-car.y)<52){player.car=true;showToast('Sentinel ligado — boa viagem!');return}
 const s=activeStep();if(missionIndex<missions.length&&near(s.x,s.y,76)){advanceMission();return}
 const market=shops.find(q=>q.kind==='MERCADO'&&near(q.x,q.y,65));if(market){openTrade();return}
 showToast('Nada para interagir por aqui.')}
function advanceMission(){const m=missions[missionIndex],s=m.steps[objectiveIndex];if(s.kind==='pickup'&&cargo.length===0){if(cargo.length<4)cargo.push({name:'Flor Neon',icon:'✿',price:160});showToast('Encomenda adicionada à carga.');}
 if(s.kind==='deliver'&&cargo.length)cargo.shift();if(s.kind==='race'&&!player.car){showToast('Pegue um veículo para completar a corrida.');return}
 if(objectiveIndex<m.steps.length-1){objectiveIndex++;showToast('OBJETIVO ATUALIZADO');}else{money+=m.reward;rep+=m.rep;missionIndex++;objectiveIndex=0;if(missionIndex>=missions.length)showDialog('CAPÍTULO CONCLUÍDO','A cidade é sua agora. Obrigado por jogar Neon Bay. Seu próximo destino?','<button class="primary-btn" data-action="close">CONTINUAR EXPLORANDO →</button>');else showDialog('MISSÃO CONCLUÍDA',`+¢${formatMoney(m.reward)} &nbsp; · &nbsp; +${m.rep} REP<br><br>Boa. A cidade ainda tem histórias para contar.`,`<button class="primary-btn" data-action="close">SEGUIR EM FRENTE →</button>`)}save();updateHUD()}
function showDialog(kicker,title,html){dialogOpen=true;$('overlay').classList.remove('hidden');$('dialog').innerHTML=`<div class="eyebrow">${kicker}</div><h2>${title}</h2><div class="dialog-actions">${html}</div>`;$('dialog').querySelectorAll('[data-action="close"]').forEach(b=>b.onclick=closeDialog)}
function closeDialog(){$('overlay').classList.add('hidden');dialogOpen=false}
$('overlay').addEventListener('click',e=>{if(e.target===$('overlay'))closeDialog()});
function openTrade(){if(dialogOpen)return;dialogOpen=true;$('overlay').classList.remove('hidden');renderTrade()}
function renderTrade(){const cargoText=cargo.length?cargo.map(c=>`<div class="option-btn"><b>${c.icon} ${c.name}</b><small>Valor de revenda ¢${c.price}</small></div>`).join(''):'<p>Sua bolsa está vazia. Itens de Neon Bay são fictícios e fazem parte do universo do jogo.</p>';$('dialog').innerHTML=`<div class="eyebrow">MERCADO DE RUA · PRODUTOS FICTÍCIOS</div><h2>Trocas rápidas</h2><p>Compre carga abstrata para missões ou venda o que carrega. Sem complicação — só economia de jogo.</p><div class="dialog-actions"><button class="option-btn" data-buy="flor"><b>✿ Flor Neon</b><small>¢160 · ocupa 1 espaço</small></button><button class="option-btn" data-buy="po"><b>✧ Pó Estelar</b><small>¢240 · ocupa 1 espaço</small></button></div><div style="font:9px 'DM Mono';color:#aab8b2;margin-top:18px">SUA CARGA · ${cargo.length}/4</div><div class="dialog-actions">${cargoText}</div><div class="dialog-actions"><button class="option-btn" data-sell><b>Vender uma unidade</b><small>Receba o valor da carga mais antiga</small></button><button class="close-btn" data-action="close">FECHAR</button></div>`;
 $('dialog').querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{let type=b.dataset.buy,price=type==='flor'?160:240;if(cargo.length>=4){showToast('Carga cheia.');return}if(money<price){showToast('Dinheiro insuficiente.');return}money-=price;cargo.push({name:type==='flor'?'Flor Neon':'Pó Estelar',icon:type==='flor'?'✿':'✧',price});updateHUD();save();renderTrade();showToast('Item adicionado à carga.')});$('dialog').querySelector('[data-sell]').onclick=()=>{if(!cargo.length){showToast('Você não tem carga para vender.');return}let item=cargo.shift();money+=item.price;updateHUD();save();renderTrade();showToast(`Venda concluída: +¢${item.price}.`)};$('dialog').querySelector('[data-action="close"]').onclick=closeDialog}
$('tradeBtn').onclick=openTrade;
function openCustomize(){if(dialogOpen)return;dialogOpen=true;$('overlay').classList.remove('hidden');const options=characters.map((c,i)=>`<option value="${i}" ${characterIndex===i?'selected':''}>${c.name} — ${c.role}</option>`).join('');$('dialog').innerHTML=`<div class="eyebrow">IDENTIDADE · ESTILO</div><h2>Quem é você hoje?</h2><p>Alterne entre personagens e escolha as cores do seu visual.</p><label>PERSONAGEM</label><select id="charSelect">${options}</select><label>COR DO VISUAL</label><input id="outfitColor" type="color" value="${player.outfit}"><div class="dialog-actions"><button class="primary-btn" id="saveStyle">SALVAR VISUAL</button><button class="close-btn" data-action="close">CANCELAR</button></div>`;$('dialog').querySelector('#saveStyle').onclick=()=>{characterIndex=Number($('charSelect').value);characters[characterIndex].outfit=$('outfitColor').value;applyCharacter();save();closeDialog();showToast('Visual atualizado!')};$('dialog').querySelector('[data-action="close"]').onclick=closeDialog}
$('customizeBtn').onclick=openCustomize;
function togglePause(){if(!running)return;paused=!paused;if(paused)showDialog('PAUSADO','Respire. Neon Bay não vai a lugar nenhum.','<button class="primary-btn" data-action="close">VOLTAR AO JOGO</button>');else closeDialog()}
$('pauseBtn').onclick=togglePause;$('playBtn').onclick=()=>{running=true;$('startScreen').classList.add('dismiss');showToast('Bem-vinda a Neon Bay, Maya.');last=performance.now();requestAnimationFrame(loop)};
function touchControl(button,key){button.addEventListener('pointerdown',e=>{e.preventDefault();keys[key]=true;button.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>button.addEventListener(ev,()=>keys[key]=false))}
document.querySelectorAll('[data-key]').forEach(b=>touchControl(b,b.dataset.key));$('mobileInteract').addEventListener('pointerdown',e=>{e.preventDefault();if(running)interact()});
function togglePause(){if(!running)return;if(paused){paused=false;closeDialog();return}paused=true;showDialog('PAUSADO','Respire. Neon Bay não vai a lugar nenhum.','<button class="primary-btn" data-action="close">VOLTAR AO JOGO</button>')}

const traffic=[];for(let i=0;i<24;i++)traffic.push({x:rand()*W,y:rand()*H,a:rand()*TAU,color:['#e4775d','#65a8a0','#d3c071','#8779ab'][Math.floor(rand()*4)],speed:22+rand()*28});
function drawRoads(){ctx.fillStyle='#283537';ctx.fillRect(0,0,W,H);
 // blocks and sidewalks
 for(let y=0;y<H;y+=CELL)for(let x=0;x<W;x+=CELL){ctx.fillStyle='#535b53';ctx.fillRect(x+ROAD/2,y+ROAD/2,CELL-ROAD,CELL-ROAD);ctx.fillStyle='#424d4b';ctx.fillRect(x+ROAD/2,y+ROAD/2,CELL-ROAD,5);ctx.fillRect(x+ROAD/2,y+ROAD/2,5,CELL-ROAD)}
 // road lanes
 ctx.fillStyle='#343d3e';for(let x=0;x<=W;x+=CELL)ctx.fillRect(x-ROAD/2,0,ROAD,H);for(let y=0;y<=H;y+=CELL)ctx.fillRect(0,y-ROAD/2,W,ROAD);
 ctx.strokeStyle='#c1bb8f55';ctx.lineWidth=2;ctx.setLineDash([17,20]);for(let x=0;x<=W;x+=CELL){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=0;y<=H;y+=CELL){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}ctx.setLineDash([]);
 // waterfront promenade
 ctx.fillStyle='#4b7773';ctx.fillRect(W-188,0,188,H);ctx.fillStyle='#9fbcab';ctx.fillRect(W-202,0,14,H);ctx.fillStyle='#79aaa0';for(let y=30;y<H;y+=65){ctx.fillRect(W-170,y,6,25)}
 // park patches
 for(const p of parks){ctx.fillStyle='#476451';ctx.fillRect(p.x,p.y,p.w,p.h);ctx.strokeStyle='#78926d';ctx.lineWidth=3;ctx.strokeRect(p.x+8,p.y+8,p.w-16,p.h-16)}
 for(const t of trees){ctx.fillStyle='#283d34';ctx.beginPath();ctx.arc(t.x+2,t.y+4,t.r+2,0,TAU);ctx.fill();ctx.fillStyle='#668554';ctx.beginPath();ctx.arc(t.x,t.y,t.r,0,TAU);ctx.fill()}
}
function drawBuildings(){for(const b of buildings){if(b.x<camera.x-vw*.7||b.x>camera.x+vw*.7||b.y<camera.y-vh*.7||b.y>camera.y+vh*.7)continue;const p=worldToScreen(b.x,b.y);const h=18+b.tall*26;ctx.fillStyle='rgba(0,0,0,.24)';ctx.fillRect(p.x+6,p.y+8,b.w,b.h);const hue=b.hue;ctx.fillStyle=`hsl(${hue} 12% ${22+b.tall*8}%)`;ctx.fillRect(p.x,p.y-h,b.w,b.h+h);ctx.fillStyle=`hsl(${hue} 14% ${31+b.tall*9}%)`;ctx.fillRect(p.x,p.y-h,b.w,5);ctx.fillStyle='#c1b288';for(let wx=11;wx<b.w-8;wx+=18)for(let wy=-h+13;wy<b.h-12;wy+=19){ctx.fillStyle=((Math.floor(wx+wy+b.roof*100)%4)===0)?'#e3c56b':'#95b3a455';ctx.fillRect(p.x+wx,p.y+wy,5,7)}ctx.fillStyle='#202b2a';ctx.fillRect(p.x+b.w*.44,p.y+b.h-15,12,15)} }
function drawShopMarkers(){for(const s of shops){const p=worldToScreen(s.x,s.y);if(p.x< -30||p.x>vw+30||p.y< -30||p.y>vh+30)continue;ctx.fillStyle='#d3ee8355';ctx.beginPath();ctx.arc(p.x,p.y,14,0,TAU);ctx.fill();ctx.fillStyle='#d8ef95';ctx.font='bold 11px monospace';ctx.textAlign='center';ctx.fillText('⇄',p.x,p.y+4)}}
function drawObjective(now){if(missionIndex>=missions.length)return;const s=activeStep(),p=worldToScreen(s.x,s.y),pulse=1+Math.sin(now/260)*.15;if(p.x< -80||p.x>vw+80||p.y< -80||p.y>vh+80)return;ctx.strokeStyle='#d2f477aa';ctx.lineWidth=2;ctx.beginPath();ctx.arc(p.x,p.y,21*pulse,0,TAU);ctx.stroke();ctx.fillStyle='#d2f477';ctx.beginPath();ctx.arc(p.x,p.y,5,0,TAU);ctx.fill();ctx.fillStyle='#d2f477';ctx.font='bold 10px "DM Mono",monospace';ctx.textAlign='center';ctx.fillText('◆',p.x,p.y-29);if(Math.hypot(s.x-currentPos().x,s.y-currentPos().y)<80){$('prompt').classList.remove('hidden');$('prompt').style.left=p.x+'px';$('prompt').style.top=(p.y+45)+'px'}else $('prompt').classList.add('hidden')}
function drawVehicle(v,isPlayer=false){const p=worldToScreen(v.x,v.y);ctx.save();ctx.translate(p.x,p.y);ctx.rotate(v.a);ctx.fillStyle='#10161688';ctx.fillRect(-18,-8,42,23);ctx.fillStyle=v.color;ctx.fillRect(-21,-11,42,21);ctx.fillStyle='#263a3b';ctx.fillRect(-10,-8,18,16);ctx.fillStyle='#c6ded2';ctx.fillRect(-8,-7,14,4);ctx.fillStyle='#ffdc8c';ctx.fillRect(17,-8,4,4);ctx.fillRect(17,4,4,4);ctx.fillStyle='#c76a52';ctx.fillRect(-21,-8,3,4);ctx.fillRect(-21,4,3,4);ctx.fillStyle='#12191a';ctx.fillRect(-14,-13,8,3);ctx.fillRect(7,-13,8,3);ctx.fillRect(-14,10,8,3);ctx.fillRect(7,10,8,3);if(isPlayer){ctx.strokeStyle='#d8ef89';ctx.lineWidth=1;ctx.strokeRect(-22,-12,44,24)}ctx.restore()}
function drawPlayer(){if(player.car)return;const p=worldToScreen(player.x,player.y);ctx.save();ctx.translate(p.x,p.y);ctx.rotate(player.a);ctx.fillStyle='#0007';ctx.beginPath();ctx.ellipse(2,8,11,6,0,0,TAU);ctx.fill();ctx.fillStyle=player.outfit;ctx.fillRect(-8,-2,16,15);ctx.fillStyle=player.color;ctx.beginPath();ctx.arc(0,-7,7,0,TAU);ctx.fill();ctx.fillStyle='#302626';ctx.fillRect(-6,-13,12,3);ctx.fillStyle='#e7e3ce';ctx.fillRect(-3,-8,2,2);ctx.fillRect(2,-8,2,2);ctx.restore()}
function drawTraffic(dt){for(const v of traffic){v.x+=Math.cos(v.a)*v.speed*dt;v.y+=Math.sin(v.a)*v.speed*dt;if(v.x<0)v.x=W;if(v.x>W)v.x=0;if(v.y<0)v.y=H;if(v.y>H)v.y=0;drawVehicle(v)}}
function drawMinimap(){const w=mini.width,h=mini.height;mctx.fillStyle='#1b2829';mctx.fillRect(0,0,w,h);mctx.fillStyle='#394545';for(let x=0;x<W;x+=CELL)mctx.fillRect(x/W*w-3,0,6,h);for(let y=0;y<H;y+=CELL)mctx.fillRect(0,y/H*h-3,w,6);mctx.fillStyle='#4d795f';for(const p of parks)mctx.fillRect(p.x/W*w,p.y/H*h,p.w/W*w,p.h/H*h);mctx.fillStyle='#4e8481';mctx.fillRect((W-188)/W*w,0,188/W*w,h);if(missionIndex<missions.length){const s=activeStep();mctx.fillStyle='#d4f17f';mctx.beginPath();mctx.arc(s.x/W*w,s.y/H*h,3.8,0,TAU);mctx.fill()}mctx.fillStyle='#fff';mctx.beginPath();mctx.arc(currentPos().x/W*w,currentPos().y/H*h,3,0,TAU);mctx.fill();mctx.strokeStyle='#ffffff77';mctx.lineWidth=1;mctx.strokeRect((camera.x-vw/2)/W*w,(camera.y-vh/2)/H*h,vw/W*w,vh/H*h)}
function draw(now,dt){ctx.clearRect(0,0,vw,vh);ctx.save();ctx.translate(vw/2-camera.x,vh/2-camera.y);drawRoads();drawBuildings();drawTraffic(dt);for(const s of shops){const p=worldToScreen(s.x,s.y);ctx.fillStyle='#d4ec8b';ctx.fillRect(s.x-4,s.y-4,8,8)}drawShopMarkers();drawObjective(now);if(player.car)drawVehicle(car,true);else{drawVehicle(car);drawPlayer()}ctx.restore();drawMinimap()}
function blocked(x,y,r){if(x<12||y<12||x>W-12||y>H-12)return true;for(const b of buildings){if(x+r>b.x&&x-r<b.x+b.w&&y+r>b.y&&y-r<b.y+b.h)return true}return false}
